/**
 * Minimal JSON-Schema export for the case-driven contracts. Generated by hand
 * (stable, versioned) rather than inferred at runtime, so schemas are
 * reproducible across process restarts.
 */
export interface JsonSchema {
  $schema: string;
  title: string;
  type: "object";
  additionalProperties: boolean;
  required: string[];
  properties: Record<string, unknown>;
}

export const CASE_INTAKE_SCHEMA: JsonSchema = {
  $schema: "https://json-schema.org/draft/2020-12/schema",
  title: "CaseIntake",
  type: "object",
  additionalProperties: false,
  required: ["victimAccountId", "incidentStartTs", "incidentEndTs", "disputedTxnIds", "narrative"],
  properties: {
    victimAccountId: { type: "string" },
    incidentStartTs: { type: "integer" },
    incidentEndTs: { type: "integer" },
    declaredLossMinor: { type: "integer", minimum: 0 },
    disputedTxnIds: { type: "array", items: { type: "string" }, minItems: 1 },
    narrative: { type: "string" },
    protectVictim: { type: "boolean" },
    idempotencyKey: { type: "string" },
  },
};

const SCHEMAS: Record<string, JsonSchema> = {
  case_intake: CASE_INTAKE_SCHEMA,
};

export function exportJsonSchema(name: string): JsonSchema | null {
  return SCHEMAS[name];
}

export function schemaNames(): string[] {
  return Object.keys(SCHEMAS);
}